// GRIMGE Prototype — curated Arcane States: unique heavy techniques and
// charge-up rituals (user, 18 Oct 2026: "alle sollen unique sein, zur Not
// welche entfernen und dafür die anderen optimieren").
//
// The roster is 15 curated atlas Arcane States plus A01 / A02 from user
// reference art, one per element / fantasy, and
// each gets SIX techniques of its own (forward / up / down × short / full)
// with its own mechanic and its own painter, plus a charge-up ritual that
// changes with the charge direction and flashes at the FULL threshold.
// Mechanics are built from a few strike primitives (line, stream, cone,
// ring, pillar, zone, bolt, chain); the look is always the form's own.
import { SigSequence, SigBolt, foesOf, groundDist, hit, massOf, DEPTH } from './signature_core.js';
import { plate, band, fallout, shard, orbitItem, hashStr, TAU, lerp, clamp01, frame, shape, line, specks, groundRing, channel, column } from './buff_v32_kit.js';
import { stoneRing, STONE, ACID_GLASS, drawWyrmHead, ghostOf } from './buff_signatures.js';
import { applyStatuses } from './buff_techniques.js';
import { giantHand } from './buff_v32_extra.js';
import { spiritArm } from './buff_v32_hands.js';
import { petal } from './buff_v32_bloom.js';
import { environment } from './environment.js';
import { combat } from './combat.js';
import { groundYForDepth } from './world.js';

const snap = (v) => Math.round(v);
const sigOf = (form) => ({ mat: form.mat, seed: hashStr(form.id) });

// ── Strike primitives (mechanics) ───────────────────────────────────────
// Every primitive returns a SigSequence; `paint(ctx, s, k)` draws it.
const status = (s, list) => (t) => applyStatuses(t, list, s.caster, s.facing);
function strike(form, p, { dur = .5, at = .06, area, damage, kx = 200, lift = 60, stun = .3, st = [], paint, x, z, after }) {
  return new SigSequence(sigOf(form), p, { dur, x, z, steps: [{ at, fn: (s, gw) => { s.strike(gw, area(s), damage, typeof kx === 'function' ? kx : (t, dx) => Math.sign(dx || s.facing) * kx, lift, stun, { onHit: status(s, st) }); after?.(s, gw); } }], draw: (ctx, s, k) => paint(ctx, s, k) });
}
const ahead = (len, w = 26, back = 8) => (s) => (t, dx, dz) => dx * s.facing > -back && dx * s.facing < len && Math.abs(dz) < w;
const around = (r, ox = 0) => (s) => (t, dx, dz) => Math.hypot(dx - s.facing * ox, dz) < r;
// A sustained stream / zone: ticks `n` times over the duration.
function ticking(form, p, { dur = .8, n = 6, area, damage, kx = 60, lift = 20, st = [], paint, x, z, final, heal = 0, extra = [] }) {
  const steps = Array.from({ length: n }, (_, i) => ({ at: .05 + i * (dur - .15) / n, fn: (s, gw) => { s.strike(gw, area(s), damage, (t, dx) => Math.sign(dx || s.facing) * kx, lift, .15, { again: true, onHit: status(s, st) }); if (heal) s.caster.hp = Math.min(s.caster.maxHp, s.caster.hp + heal); } }));
  steps.push(...extra);
  if (final) steps.push({ at: dur - .08, fn: (s, gw) => s.strike(gw, final.area(s), final.damage, (t, dx) => Math.sign(dx || s.facing) * (final.kx ?? 320), final.lift ?? 180, .4, { again: true, onHit: status(s, final.st ?? st) }) });
  return new SigSequence(sigOf(form), p, { dur, x, z, steps, draw: (ctx, s, k) => paint(ctx, s, k) });
}
// Projectiles fired by a controller sequence (kept in the spell system).
function volley(form, p, { shots, dur = .4, paint = () => {} }) {
  return new SigSequence(sigOf(form), p, { dur, steps: shots.map((o, i) => ({ at: o.at ?? i * .06, fn: (s) => s.system?.addSpell(new SigBolt({ x: s.caster.x + s.facing * 22, z: s.caster.z, height: (s.caster.worldHeight ?? 0) + (o.h ?? 42), team: s.team, mat: o.mat ?? form.mat, vx: s.facing * (o.speed ?? 640), vz: o.vz ?? 0, damage: o.damage, kind: o.kind ?? 'crystal', size: o.size ?? 6, life: o.life ?? .9, pierce: o.pierce, homing: o.homing, turn: o.turn, kx: o.kx ?? 160, lift: o.lift ?? 50, stun: o.stun ?? .25, seed: hashStr(form.id) + i, onHit: o.st ? (t) => applyStatuses(t, o.st, s.caster, s.facing) : o.onHit, onBurst: o.burst }), 'B') })), draw: (ctx, s, k) => paint(ctx, s, k) });
}
// A lightning-like chain from the first target in front to the nearest others.
function chain(form, p, { jumps = 4, damage, range = 230, st = [], paint }) {
  return new SigSequence(sigOf(form), p, { dur: .6, data: { links: [] }, steps: [{ at: .06, fn: (s, gw) => {
    let from = { x: s.x + s.facing * 20, z: s.z }; const done = new Set();
    for (let j = 0; j <= jumps; j++) {
      const next = foesOf(gw, s.team).filter((t) => !done.has(t) && (j > 0 || (t.x - s.x) * s.facing > -10)).sort((a, b) => groundDist(a, from) - groundDist(b, from))[0];
      if (!next || groundDist(next, from) > (j ? 150 : range)) break;
      done.add(next); s.links.push([from, { x: next.x, z: next.z }]); hit(next, damage * (1 - j * .1), Math.sign(next.x - from.x || s.facing) * 120, 60, .3); applyStatuses(next, st, s.caster, s.facing); from = next;
    }
    if (!s.links.length) s.links.push([from, { x: s.x + s.facing * range, z: s.z }]);
  } }], draw: (ctx, s, k) => paint(ctx, s, k) });
}

// ── Painting helpers ─────────────────────────────────────────────────────
const fade = (k, inT = .12, outT = .3) => Math.min(1, k / inT, (1 - k) / outT);
const gy = (s) => groundYForDepth(s.z);
const zig = (x0, y0, x1, y1, n, amp, seed = 0) => Array.from({ length: n + 1 }, (_, i) => { const u = i / n; return [lerp(x0, x1, u), lerp(y0, y1, u) + (i && i < n ? Math.sin(seed + i * 2.7) * amp : 0)]; });

